package com.trombokendu.chronos.ui;import javax.swing.table.*;import java.util.*;import com.trombokendu.chronos.ledger.*;import com.trombokendu.chronos.domain.*;public final class LedgerTableModel extends AbstractTableModel{private static final long serialVersionUID=1L;private final String[] cols={"Event","Date","Kind","Category","Amount (₹)","Note"};private transient List<StoredEvent> rows=List.of();public void setRows(List<StoredEvent> r){rows=List.copyOf(r);fireTableDataChanged();}public int getRowCount(){return rows.size();}public int getColumnCount(){return cols.length;}public String getColumnName(int c){return cols[c];}public Object getValueAt(int r,int c){LedgerEvent e=rows.get(r).event();return switch(e){case TransactionPosted x->switch(c){case 0->x.eventId().toString().substring(0,8);case 1->x.valueDate();case 2->x.kind();case 3->x.category().displayName();case 4->x.amount();case 5->x.note();default->"";};case TransactionVoided x->c==0?x.eventId():c==5?"Voided: "+x.reason():"";case BudgetSet x->c==0?x.eventId():c==5?"Budget set "+x.monthlyBudget():"";case RecurringRuleDefined x->c==0?x.eventId():c==5?"Recurring "+x.description():"";};}}
